static List<Integer> topK(List<Integer> scores, int k) {
    PriorityQueue<Integer> best = new PriorityQueue<>(Comparator.reverseOrder());
    best.addAll(scores);
    return new ArrayList<>(best).subList(0, Math.min(k, best.size()));
}

